join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P203', 'P161', 'P168', 'P173', 'P202', 'P042', 'P077', 'P101', 'P112', 'P116', 'P118', 'P128', 'P136', 'P163', 'P026', 'P047', 'P048', 'P108', 'P158', 'P177', 'P180', 'P200', 'P219', 'P046', 'P111')) <> 25 then
    raise exception 'a character of the sixth batch has no kit';
  end if;
end $$;
